import{_ as t,o,c as a,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"Mobile Authentication, Deep-Link Google OAuth, 2FA Verify & Biometric App Lock","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/08-mobile-application/mobile-auth/spec.md","filePath":"feature/modules/08-mobile-application/mobile-auth/spec.md"}'),c={name:"feature/modules/08-mobile-application/mobile-auth/spec.md"};function r(n,e,s,l,d,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="mobile-authentication-deep-link-google-oauth-2fa-verify-biometric-app-lock" tabindex="-1">Mobile Authentication, Deep-Link Google OAuth, 2FA Verify &amp; Biometric App Lock <a class="header-anchor" href="#mobile-authentication-deep-link-google-oauth-2fa-verify-biometric-app-lock" aria-label="Permalink to &quot;Mobile Authentication, Deep-Link Google OAuth, 2FA Verify &amp; Biometric App Lock&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>mobile-auth</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>08-mobile-application</code> — BrandHub Mobile Application (Expo SDK 58 / React Native 0.88)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Guest, Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>mobile-auth</code>, <code>mobile-native-enhancements (Biometric AppLockGate &amp; SecureStore)</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/01-authentication/README.html">3.2 Authentication &amp; Authorization</a> (<code>3.2.1–3.2.9</code>)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Deliver production-grade authentication and on-device session security on <code>brandhub-mobile-app</code> (Expo SDK 58, React Native 0.88): Email/Password Sign In, Sign Up + 60s OTP Verification, Forgot/Reset Password + Account Activation deep links, <strong>Google OAuth (<code>expo-web-browser</code> / <code>expo-auth-session</code> via <code>?client=mobile</code> -&gt; <code>brandhub://oauth-callback</code>)</strong>, 2FA TOTP verification, <code>expo-secure-store</code> token persistence with single-flight refresh, and <strong>Biometric / Device-Passcode <code>AppLockGate</code></strong> (<code>expo-local-authentication</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As a mobile user (<code>Guest -&gt; Owner / Manager / Creator / Client / Admin</code>), I want seamless Email, OTP, 2FA, and Google OAuth sign-in plus optional FaceID/TouchID/Passcode App Lock after <code>60s</code> in background so client data on my phone stays protected.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Complete Auth Screen Stack (<code>AuthNavigator.tsx</code>):</strong> <code>LoginScreen.tsx</code>, <code>RegisterScreen.tsx</code>, <code>VerifyOtpScreen.tsx</code> (60s resend timer), <code>ForgotPasswordScreen.tsx</code>, <code>ResetPasswordScreen.tsx</code>, <code>TwoFactorVerifyScreen.tsx</code>, and <code>ActivateAccountScreen.tsx</code> wired to <code>authService.ts</code> and <code>authStore.ts</code>.</li><li><strong>Mobile Google OAuth (<code>2026-11-11-mobile-google-oauth-link.sql</code>):</strong> Initiates <code>/api/v1/auth/oauth/google?client=mobile</code> inside <code>expo-web-browser</code> system auth session and handles <code>brandhub://oauth-callback</code> deep-link token exchange cleanly.</li><li><strong><code>expo-secure-store</code> Single-Flight Refresh &amp; Safe Sign-Out:</strong> <code>api.ts</code> queues concurrent <code>401</code> requests behind one <code>/api/v1/auth/refresh</code> call; <code>confirmSignOut.ts</code> revokes server session, wipes <code>SecureStore</code>, clears <code>TanStack Query</code> caches, and cancels scheduled local task reminders.</li><li><strong>Biometric / Passcode <code>AppLockGate</code> (<code>mobile-native-enhancements</code> AC-L1..L7):</strong> <code>AppLockGate.tsx</code> (<code>appLock.ts</code> + <code>deviceFeaturesStore.ts</code>) requires successful <code>expo-local-authentication</code> check to enable/disable, locks on cold launch and after <code>&gt;= 60s</code> background (including backward clock-tamper guard), blocks Android hardware Back &amp; screen-reader leakage while locked, always provides an emergency Sign Out escape hatch, and preserves active screen/drafts/uploads upon unlock.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>src/i18n/locales/en.json</code> &amp; <code>src/i18n/locales/vi/common.json</code> (<code>auth.*</code>, <code>security.appLock.*</code>, <code>api-errors.vi.json</code> via <code>tr()</code>)) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> Parity with <code>pages/auth/{LoginPage,RegisterPage,VerifyOtpPage,TwoFactorVerifyPage,OAuthCallbackPage,ActivateAccountPage}.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/navigation/AuthNavigator.tsx</code>, <code>src/screens/auth/*</code>, <code>src/screens/settings/SecuritySettingsScreen.tsx</code>, <code>src/components/common/AppLockGate.tsx</code>, <code>src/store/{authStore,deviceFeaturesStore}.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;">`POST /api/v1/auth/{login</td><td style="text-align:left;">register</td><td style="text-align:left;">verify-otp</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/auth/oauth/google?client=mobile -&gt; brandhub://oauth-callback</code></td><td style="text-align:left;">OAuth 2.0 Redirect</td><td style="text-align:left;"><code>GoogleOAuthController</code> -&gt; <code>expo-web-browser</code> / <code>expo-linking</code></td></tr><tr><td style="text-align:left;">`POST /api/v1/auth/activation/{verify</td><td style="text-align:left;">complete}`</td><td style="text-align:left;">Activation Token</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Device Without OS Screen Lock Enrolled:</strong> <code>AppLockGate</code> blocks enabling App Lock with a localized prompt guiding user to OS Security Settings.</li><li><strong>Clock Rolled Back While Backgrounded:</strong> Monotonic/timestamp delta check forces lock if elapsed <code>&lt; 0</code> or <code>&gt;= 60,000 ms</code>.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/01-authentication/README.html">3.2 Authentication &amp; Authorization</a> (<code>3.2.1–3.2.9</code>)</li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA 02 Authentication &amp; Profile</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const p=t(c,[["render",r]]);export{h as __pageData,p as default};
